49	static void usage(int code, int keep_it_short) {
50	  FILE *f = stderr;
51	
52	  if (code == 0)
53	    f = stdout;
54	
55	  int ret = fprintf(f,
56	    "jq - commandline JSON processor [version %s]\n"
57	    "\nUsage:\t%s [options] <jq filter> [file...]\n"
58	    "\t%s [options] --args <jq filter> [strings...]\n"
59	    "\t%s [options] --jsonargs <jq filter> [JSON_TEXTS...]\n\n"
60	    "jq is a tool for processing JSON inputs, applying the given filter to\n"
61	    "its JSON text inputs and producing the filter's results as JSON on\n"
62	    "standard output.\n\n"
63	    "The simplest filter is ., which copies jq's input to its output\n"
64	    "unmodified except for formatting. For more advanced filters see\n"
65	    "the jq(1) manpage (\"man jq\") and/or https://jqlang.github.io/jq/.\n\n"
66	    "Example:\n\n\t$ echo '{\"foo\": 0}' | jq .\n"
67	    "\t{\n\t  \"foo\": 0\n\t}\n\n",
68	    JQ_VERSION, progname, progname, progname);
69	  if (keep_it_short) {
70	    fprintf(f,
71	      "For listing the command options, use %s --help.\n",
72	      progname);
73	  } else {
74	    (void) fprintf(f,
75	      "Command options:\n"
76	      "  -n, --null-input          use `null` as the single input value;\n"
77	      "  -R, --raw-input           read each line as string instead of JSON;\n"
78	      "  -s, --slurp               read all inputs into an array and use it as\n"
79	      "                            the single input value;\n"
80	      "  -c, --compact-output      compact instead of pretty-printed output;\n"
81	      "  -r, --raw-output          output strings without escapes and quotes;\n"
82	      "      --raw-output0         implies -r and output NUL after each output;\n"
83	      "  -j, --join-output         implies -r and output without newline after\n"
84	      "                            each output;\n"
85	      "  -a, --ascii-output        output strings by only ASCII characters\n"
86	      "                            using escape sequences;\n"
87	      "  -S, --sort-keys           sort keys of each object on output;\n"
88	      "  -C, --color-output        colorize JSON output;\n"
89	      "  -M, --monochrome-output   disable colored output;\n"
90	      "      --tab                 use tabs for indentation;\n"
91	      "      --indent n            use n spaces for indentation (max 7 spaces);\n"
92	      "      --unbuffered          flush output stream after each output;\n"
93	      "      --stream              parse the input value in streaming fashion;\n"
94	      "      --stream-errors       implies --stream and report parse error as\n"
95	      "                            an array;\n"
96	      "      --seq                 parse input/output as application/json-seq;\n"
97	      "  -f, --from-file file      load filter from the file;\n"
98	      "  -L directory              search modules from the directory;\n"
99	      "      --arg name value      set $name to the string value;\n"
100	      "      --argjson name value  set $name to the JSON value;\n"
101	      "      --slurpfile name file set $name to an array of JSON values read\n"
102	      "                            from the file;\n"
103	      "      --rawfile name file   set $name to string contents of file;\n"
104	      "      --args                consume remaining arguments as positional\n"
105	      "                            string values;\n"
106	      "      --jsonargs            consume remaining arguments as positional\n"
107	      "                            JSON values;\n"
108	      "  -e, --exit-status         set exit status code based on the output;\n"
109	#ifdef WIN32
110	      "  -b, --binary              open input/output streams in binary mode;\n"
111	#endif
112	      "  -V, --version             show the version;\n"
113	      "  --build-configuration     show jq's build configuration;\n"
114	      "  -h, --help                show the help;\n"
115	      "  --                        terminates argument processing;\n\n"
116	      "Named arguments are also available as $ARGS.named[], while\n"
117	      "positional arguments are available as $ARGS.positional[].\n");
118	  }
119	  exit((ret < 0 && code == 0) ? 2 : code);
120	}
