181	static const char *skip_shebang(const char *p) {
182	  if (strncmp(p, "#!", sizeof("#!") - 1) != 0)
183	    return p;
184	  const char *n = strchr(p, '\n');
185	  if (n == NULL || n[1] != '#')
186	    return p;
187	  n = strchr(n + 1, '\n');
188	  if (n == NULL || n[1] == '#' || n[1] == '\0' || n[-1] != '\\' || n[-2] == '\\')
189	    return p;
190	  n = strchr(n + 1, '\n');
191	  if (n == NULL)
192	    return p;
193	  return n+1;
194	}
