196	static int process(jq_state *jq, jv value, int flags, int dumpopts, int options) {
197	  int ret = JQ_OK_NO_OUTPUT; // No valid results && -e -> exit(4)
198	  jq_start(jq, value, flags);
199	  jv result;
200	  while (jv_is_valid(result = jq_next(jq))) {
201	    if ((options & RAW_OUTPUT) && jv_get_kind(result) == JV_KIND_STRING) {
202	      if (options & ASCII_OUTPUT) {
203	        jv_dumpf(jv_copy(result), stdout, JV_PRINT_ASCII);
204	      } else if ((options & RAW_OUTPUT0) && strlen(jv_string_value(result)) != (unsigned long)jv_string_length_bytes(jv_copy(result))) {
205	        jv_free(result);
206	        result = jv_invalid_with_msg(jv_string(
207	              "Cannot dump a string containing NUL with --raw-output0 option"));
208	        break;
209	      } else {
210	        priv_fwrite(jv_string_value(result), jv_string_length_bytes(jv_copy(result)),
211	            stdout, dumpopts & JV_PRINT_ISATTY);
212	      }
213	      ret = JQ_OK;
214	      jv_free(result);
215	    } else {
216	      if (jv_get_kind(result) == JV_KIND_FALSE || jv_get_kind(result) == JV_KIND_NULL)
217	        ret = JQ_OK_NULL_KIND;
218	      else
219	        ret = JQ_OK;
220	      if (options & SEQ)
221	        priv_fwrite("\036", 1, stdout, dumpopts & JV_PRINT_ISATTY);
222	      jv_dump(result, dumpopts);
223	    }
224	    if (!(options & RAW_NO_LF))
225	      priv_fwrite("\n", 1, stdout, dumpopts & JV_PRINT_ISATTY);
226	    if (options & RAW_OUTPUT0)
227	      priv_fwrite("\0", 1, stdout, dumpopts & JV_PRINT_ISATTY);
228	    if (options & UNBUFFERED_OUTPUT)
229	      fflush(stdout);
230	  }
231	  if (jq_halted(jq)) {
232	    // jq program invoked `halt` or `halt_error`
233	    jv exit_code = jq_get_exit_code(jq);
234	    if (!jv_is_valid(exit_code))
235	      ret = JQ_OK;
236	    else if (jv_get_kind(exit_code) == JV_KIND_NUMBER)
237	      ret = jv_number_value(exit_code);
238	    else
239	      ret = JQ_ERROR_UNKNOWN;
240	    jv_free(exit_code);
241	    jv error_message = jq_get_error_message(jq);
242	    if (jv_get_kind(error_message) == JV_KIND_STRING) {
243	      // No prefix should be added to the output of `halt_error`.
244	      priv_fwrite(jv_string_value(error_message), jv_string_length_bytes(jv_copy(error_message)),
245	          stderr, dumpopts & JV_PRINT_ISATTY);
246	    } else if (jv_get_kind(error_message) == JV_KIND_NULL) {
247	      // Halt with no output
248	    } else if (jv_is_valid(error_message)) {
249	      error_message = jv_dump_string(error_message, 0);
250	      fprintf(stderr, "%s\n", jv_string_value(error_message));
251	    } // else no message on stderr; use --debug-trace to see a message
252	    fflush(stderr);
253	    jv_free(error_message);
254	  } else if (jv_invalid_has_msg(jv_copy(result))) {
255	    // Uncaught jq exception
256	    jv msg = jv_invalid_get_msg(jv_copy(result));
257	    jv input_pos = jq_util_input_get_position(jq);
258	    if (jv_get_kind(msg) == JV_KIND_STRING) {
259	      fprintf(stderr, "jq: error (at %s): %s\n",
260	              jv_string_value(input_pos), jv_string_value(msg));
261	    } else {
262	      msg = jv_dump_string(msg, 0);
263	      fprintf(stderr, "jq: error (at %s) (not a string): %s\n",
264	              jv_string_value(input_pos), jv_string_value(msg));
265	    }
266	    ret = JQ_ERROR_UNKNOWN;
267	    jv_free(input_pos);
268	    jv_free(msg);
269	  }
270	  jv_free(result);
271	  return ret;
272	}
