280	static void stderr_cb(void *data, jv input) {
281	  if (jv_get_kind(input) == JV_KIND_STRING) {
282	    int dumpopts = *(int *)data;
283	    priv_fwrite(jv_string_value(input), jv_string_length_bytes(jv_copy(input)),
284	        stderr, dumpopts & JV_PRINT_ISATTY);
285	  } else {
286	    input = jv_dump_string(input, 0);
287	    fprintf(stderr, "%s", jv_string_value(input));
288	  }
289	  jv_free(input);
