438	      }
439	      if (isoption(argv[i], 0, "unbuffered", &short_opts)) {
440	        options |= UNBUFFERED_OUTPUT;
441	        continue;
442	      }
443	      if (isoption(argv[i], 'S', "sort-keys", &short_opts)) {
444	        options |= SORTED_OUTPUT;
445	        if (!short_opts) continue;
446	      }
447	      if (isoption(argv[i], 'R', "raw-input", &short_opts)) {
448	        options |= RAW_INPUT;
449	        if (!short_opts) continue;
450	      }
451	      if (isoption(argv[i], 'n', "null-input", &short_opts)) {
452	        options |= PROVIDE_NULL;
453	        if (!short_opts) continue;
454	      }
455	      if (isoption(argv[i], 'f', "from-file", &short_opts)) {
456	        options |= FROM_FILE;
457	        if (!short_opts) continue;
458	      }
459	      if (isoption(argv[i], 'b', "binary", &short_opts)) {
460	#ifdef WIN32
461	        fflush(stdout);
462	        fflush(stderr);
463	        _setmode(fileno(stdin),  _O_BINARY);
464	        _setmode(fileno(stdout), _O_BINARY);
