468	      }
469	      if (isoption(argv[i], 0, "tab", &short_opts)) {
470	        dumpopts &= ~JV_PRINT_INDENT_FLAGS(7);
471	        dumpopts |= JV_PRINT_TAB | JV_PRINT_PRETTY;
472	        continue;
473	      }
474	      if (isoption(argv[i], 0, "indent", &short_opts)) {
475	        if (i >= argc - 1) {
476	          fprintf(stderr, "%s: --indent takes one parameter\n", progname);
477	          die();
478	        }
479	        dumpopts &= ~(JV_PRINT_TAB | JV_PRINT_INDENT_FLAGS(7));
