498	        parser_flags |= JV_PARSE_STREAMING | JV_PARSE_STREAM_ERRORS;
499	        continue;
500	      }
501	      if (isoption(argv[i], 'e', "exit-status", &short_opts)) {
502	        options |= EXIT_STATUS;
503	        if (!short_opts) continue;
504	      }
505	      // FIXME: For --arg* we should check that the varname is acceptable
506	      if (isoption(argv[i], 0, "args", &short_opts)) {
507	        further_args_are_strings = 1;
508	        further_args_are_json = 0;
509	        continue;
510	      }
511	      if (isoption(argv[i], 0, "jsonargs", &short_opts)) {
512	        further_args_are_strings = 0;
513	        further_args_are_json = 1;
514	        continue;
515	      }
516	      if (isoption(argv[i], 0, "arg", &short_opts)) {
517	        if (i >= argc - 2) {
518	          fprintf(stderr, "%s: --arg takes two parameters (e.g. --arg varname value)\n", progname);
519	          die();
520	        }
521	        if (!jv_object_has(jv_copy(program_arguments), jv_string(argv[i+1])))
522	          program_arguments = jv_object_set(program_arguments, jv_string(argv[i+1]), jv_string(argv[i+2]));
523	        i += 2; // skip the next two arguments
524	        continue;
525	      }
526	      if (isoption(argv[i], 0, "argjson", &short_opts)) {
527	        if (i >= argc - 2) {
